UPDATE routes r
SET
  name = osrm_routes.name,
  color = osrm_routes.color,
  buffer_radius_m = 8,
  outbound_geom = ST_SetSRID(ST_GeomFromGeoJSON(osrm_routes.outbound_geojson), 4326),
  inbound_geom = ST_SetSRID(ST_GeomFromGeoJSON(osrm_routes.inbound_geojson), 4326)
FROM osrm_routes
WHERE r.route_id = osrm_routes.route_id;

DELETE FROM geofences;

INSERT INTO geofences (name, type, route_id, geom)
SELECT
  concat('Koridor OSRM 8m - ', route_id, ' #', dump.path[1]),
  'ROUTE_CORRIDOR',
  route_id,
  dump.geom::geometry(Polygon, 4326)
FROM routes
CROSS JOIN LATERAL ST_Dump(ST_Buffer(ST_Union(outbound_geom, inbound_geom)::geography, 8)::geometry) AS dump
WHERE route_id IN ('01', '02', '03')
  AND outbound_geom IS NOT NULL
  AND inbound_geom IS NOT NULL;

COMMIT;
